// Rust guideline compliant 2026-02-21
use gpui_mesh::{CellType,DataSet};
use gpui_profiler::AllocProbe;
use std::{hint::black_box,time::Instant};
fn cpu_ns()->u128 {
 let mut ts=libc::timespec{tv_sec:0,tv_nsec:0};
 // SAFETY: ts is writable storage for this synchronous clock call, which
 // retains no pointer; status and timestamp are checked before conversion.
 let rc=unsafe{libc::clock_gettime(libc::CLOCK_PROCESS_CPUTIME_ID,&mut ts)};
 assert_eq!(rc,0);assert!(ts.tv_sec>=0 && (0..1_000_000_000).contains(&ts.tv_nsec));
 ts.tv_sec as u128*1_000_000_000+ts.tv_nsec as u128
}
fn fold(h:&mut u64,b:&[u8]) {for &v in b {*h=(*h^u64::from(v)).wrapping_mul(0x100000001b3);}}
fn hash(d:&DataSet)->u64 {let mut h=0xcbf29ce484222325;
 for p in d.positions.iter(){for v in p {fold(&mut h,&v.to_bits().to_le_bytes());}}
 for t in d.cells.types.iter(){let code=match t {CellType::Vertex=>0,CellType::Line=>1,CellType::Triangle=>2,CellType::Quad=>3,CellType::Tetra=>4,CellType::Hexahedron=>5,CellType::Wedge=>6,CellType::Pyramid=>7,CellType::Polygon=>8};fold(&mut h,&[code]);}
 for v in d.cells.offsets.iter(){fold(&mut h,&v.to_le_bytes());}for v in d.cells.connectivity.iter(){fold(&mut h,&v.to_le_bytes());}h
}
fn payload(d:&DataSet)->usize {d.positions.len()*24+d.cells.types.len()*size_of::<CellType>()+d.cells.offsets.len()*8+d.cells.connectivity.len()*4}
fn axes(n:usize)->[Vec<f64>;3] {std::array::from_fn(|a|(0..n).map(|i|[0.125,-1.5,2.0][a]+i as f64*[0.25,0.5,-0.75][a]).collect())}
fn positions(dims:[usize;3],warped:bool)->Vec<[f64;3]> {
 let mut out=Vec::with_capacity(dims.into_iter().product());
 for k in 0..dims[2]{for j in 0..dims[1]{for i in 0..dims[0]{let p=[0.125+i as f64*0.25,-1.5+j as f64*0.5,2.0-k as f64*0.75];out.push(if warped{[p[0]+0.01*p[1]*p[2],p[1]+0.02*p[0]*p[2],p[2]+0.03*p[0]*p[1]]}else{p});}}}out
}
fn measure<I>(dims:[usize;3],method:&str,mut input:impl FnMut()->I,mut build:impl FnMut(I)->DataSet) {
 let reference=build(input());reference.validate().unwrap();let expected=hash(&reference);let bytes=payload(&reference);let cells=reference.cell_count();drop(reference);
 let(mut times,mut cpus,mut calls,mut allocations)=(Vec::new(),Vec::new(),Vec::new(),Vec::new());
 let warm=build(input());assert_eq!(hash(&warm),expected);drop(warm);
 for _ in 0..5 {let prepared=input();let mut probe=AllocProbe::new();let before=cpu_ns();let start=Instant::now();let data=black_box(build(prepared));let elapsed=start.elapsed().as_nanos();let cpu=cpu_ns()-before;let a=probe.sample("grid-construction");
  times.push(elapsed);cpus.push(cpu);calls.push(a.count);allocations.push(a.bytes);data.validate().unwrap();assert_eq!(hash(&data),expected);assert_eq!(payload(&data),bytes);drop(data);
 }
 println!(r#"{{"dims":{dims:?},"method":"{method}","cells":{cells},"payload_bytes":{bytes},"output_hash":"{expected:016x}","times_ns":{times:?},"cpu_times_ns":{cpus:?},"allocation_calls":{calls:?},"allocated_bytes":{allocations:?},"allocator_instrumentation":{}}}"#,cfg!(feature="allocations"));
}
fn rss(method:&str,n:usize) {
 let dims=[n;3];let data=match method {
  "affine"=>DataSet::structured_grid("probe",dims,[0.125,-1.5,2.0],[0.25,0.5,-0.75]).unwrap(),
  "rectilinear"=>{let a=axes(n);DataSet::rectilinear_grid("probe",&a[0],&a[1],&a[2]).unwrap()},
  "curvilinear"=>DataSet::curvilinear_grid("probe",dims,positions(dims,true)).unwrap(),
  _=>panic!("method")
 };data.validate().unwrap();println!(r#"{{"method":"{method}","n":{n},"payload_bytes":{},"output_hash":"{:016x}"}}"#,payload(&data),hash(&data));black_box(data);
}
fn main(){let args=std::env::args().collect::<Vec<_>>();if args.get(1).is_some_and(|v|v=="--rss"){rss(&args[2],args[3].parse().unwrap());return;}
 for n in [16,48,96] {let dims=[n;3];
  measure(dims,"affine",||(),|()|DataSet::structured_grid("probe",dims,[0.125,-1.5,2.0],[0.25,0.5,-0.75]).unwrap());
  let a=axes(n);measure(dims,"rectilinear",||(),|()|DataSet::rectilinear_grid("probe",&a[0],&a[1],&a[2]).unwrap());
  let template=positions(dims,true);measure(dims,"curvilinear",||template.clone(),|p|DataSet::curvilinear_grid("probe",dims,p).unwrap());
 }
 for dims in [[64,64,1],[64,1,64],[1,64,64],[4096,1,1],[1,4096,1],[1,1,4096]] {measure(dims,"affine",||(),|()|DataSet::structured_grid("probe",dims,[0.125,-1.5,2.0],[0.25,0.5,-0.75]).unwrap());}
}

